<template><main class="page"><PageHeader :title="t('nav.about')"><template #primary><button class="xdev-btn xdev-btn--secondary" data-action="check-update" @click="$emit('check-update')">{{t('settings.check_update')}}</button></template></PageHeader><SectionCard><dl><template v-for="row in rows" :key="row.label"><dt>{{row.label}}</dt><dd><CopyableValue :value="row.value||'-'"/></dd></template><dt>{{t('about.repo')}}</dt><dd><a v-if="safeRepo" :href="info.repoURL" target="_blank" rel="noopener noreferrer">{{info.repoURL}}</a><CopyableValue v-else :value="info.repoURL||'-'"/></dd></dl></SectionCard></main></template><script setup>import{computed}from'vue';import CopyableValue from'../components/CopyableValue.vue';import PageHeader from'../components/PageHeader.vue';import SectionCard from'../components/SectionCard.vue';const props=defineProps({t:{type:Function,required:true},info:{type:Object,default:()=>({})}});defineEmits(['check-update']);const safeRepo=computed(()=>{try{return['http:','https:'].includes(new URL(props.info.repoURL).protocol)}catch{return false}});const rows=computed(()=>[['app_name',props.info.appName],['version',props.info.version],['build_date',props.info.buildDate],['go_version',props.info.goVersion],['wails_version',props.info.wailsVersion],['platform',`${props.info.platform||'-'}/${props.info.arch||'-'}`],['license',props.info.license]].map(([k,value])=>({label:props.t(`about.${k}`),value})));</script><style scoped>.page{width:min(var(--xdev-reading-max-width),100%);margin:0 auto;display:grid;gap:var(--xdev-section-gap);min-width:0}dl{display:grid;grid-template-columns:max-content minmax(0,1fr);gap:var(--xdev-space-3)}dd{margin:0;min-width:0}a{overflow-wrap:anywhere;color:var(--xdev-accent)}@media(max-width:640px){dl{grid-template-columns:1fr}dt{font-weight:700}}</style>
